import {connectFacilityReview,facilityQueue,facilityDetail} from './facility-review.js';
import {connectERP,dashboard,financeWorkspace} from './erp.js';
const content=document.querySelector('#content'),status=document.querySelector('#status');
let staff,partners=[],currentOrder=null;
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
function button(parent,title,run){const b=node('button',title);b.onclick=()=>guard(run);parent.append(b);return b;}
async function guard(run){status.textContent='';try{await run();}catch(e){status.textContent=e.message;}}
async function api(path,method='GET',input){const response=await fetch('/api/ops'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:input?JSON.stringify(input):undefined,redirect:'error'});const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error||'Could not complete this request.'),{status:response.status});return data;}
const key=()=>`ops-pending:${staff.id}`;
function pending(){const box=document.querySelector('#pending');box.replaceChildren();if(!staff)return;const saved=sessionStorage.getItem(key());if(saved){box.append(node('p','An action is awaiting confirmation. Retry it before submitting another change.','notice'));button(box,'Retry pending action',retry);}}
async function retry(){const p=JSON.parse(sessionStorage.getItem(key()));if(!p)return;try{await api(p.path,p.method,p.input);sessionStorage.removeItem(key());pending();if(p.order)await (p.path.includes('/finance/')?financeWorkspace(p.order):openOrder(p.order));else if(p.path.startsWith('/facilities/'))await facilityDetail(p.path.split('/')[2]);else await showPartners();}catch(e){if(e.status>=400&&e.status<500&&![401,408,429].includes(e.status))sessionStorage.removeItem(key());pending();throw e;}}
async function mutate(path,method,input,order=null){if(sessionStorage.getItem(key()))throw new Error('Retry the pending action first.');sessionStorage.setItem(key(),JSON.stringify({path,method,input:{...input,commandId:crypto.randomUUID()},order}));pending();await retry();}
function field(form,name,title,type='text',value='',options=[]){const l=node('label',title),e=document.createElement(type==='textarea'?'textarea':type==='select'?'select':'input');if(type!=='select'&&type!=='textarea')e.type=type;e.name=name;if(type==='select')for(const [v,label]of options){const o=node('option',label);o.value=v;e.append(o);}e.value=value;e.required=true;l.append(e);form.append(l);return e;}
function form(parent,title,fields,submit){const details=node('details'),heading=node('summary',title),f=node('form');details.append(heading,f);parent.append(details);for(const spec of fields)field(f,...spec);const b=node('button','Save');b.className='primary';f.append(b);f.onsubmit=e=>{e.preventDefault();guard(async()=>{b.disabled=true;try{await submit(Object.fromEntries(new FormData(f)));}finally{b.disabled=false;}});};return f;}
function card(parent,title,lines){const c=node('article',undefined,'card');c.append(node('h3',title));for(const line of lines)c.append(node('p',line));parent.append(c);return c;}
function recordText(data){const labels={quantity:'Actual quantity',unit:'Unit',acceptedQuantity:'Accepted quantity',condition:'Condition',location:'Location (manual)',capturedAt:'Evidence time',message:'Note',noPhotoReason:'Missing photo explanation',amount:'Logistics charge ₹',basis:'Charge basis',payer:'Payer',payee:'Payee',source:'Source',reason:'Reason',partnerName:'Transport partner',partnerContact:'Partner contact',start:'Window start',end:'Window end',instructions:'Instructions',resolution:'Resolution'};const lines=Object.entries(labels).filter(([key])=>data[key]!==undefined&&data[key]!==null&&data[key]!=='').map(([key,label])=>label+': '+data[key]);if(data.supersedes)lines.push('Correction: original evidence remains in the history.');return lines.join('\n');}
function localDate(value){return value?new Date(value).toLocaleString():'Not scheduled';}
async function board(after=''){currentOrder=null;const d=await api('/orders'+(after?'?after='+encodeURIComponent(after):''));content.replaceChildren(node('h2','Orders & logistics'));content.append(node('p','Schedule collections, review custody exceptions and coordinate returns.','meta'));const filter=field(content,'filter','Filter this page by area, recycler or status');filter.required=false;const grid=node('div',undefined,'cards');content.append(grid);const render=()=>{grid.replaceChildren();const search=filter.value.toLowerCase();for(const o of d.orders.filter(o=>[o.locality,o.recycler,o.collector,o.logistics_state,o.state].join(' ').toLowerCase().includes(search))){const c=card(grid,o.collector+' → '+o.recycler,[o.locality,`Delivery: ${o.state==='cancelled'?'cancelled':o.logistics_state}`,`${o.open_issues} open issue(s)`]);button(c,'Open order',()=>openOrder(o.id));}if(!grid.childElementCount)grid.append(node('p','No matching orders on this page.'));};filter.oninput=render;render();if(d.nextCursor)button(content,'Next page',()=>board(d.nextCursor));if(after)button(content,'First page',()=>board());}
async function showPartners(){currentOrder=null;partners=(await api('/partners')).partners;content.replaceChildren(node('h2','Transport partners'));content.append(node('p','Only active partners serving the collection area can be scheduled. Contact details are shared with the order parties.','meta'));const fields=p=>[['name','Partner name','text',p.name||''],['contact','Dispatch contact','text',p.contact||''],['areas','Service areas, separated by commas','text',p.areas_json?JSON.parse(p.areas_json).join(', '):''],['status','Availability','select',p.status||'active',[['active','Active'],['unavailable','Unavailable']]]];const save=p=>v=>mutate('/partners/'+(p.id||crypto.randomUUID()),'PUT',{...v,areas:v.areas.split(',').map(x=>x.trim()),expectedVersion:p.version||0});if(['operations','operations_finance'].includes(staff.role))form(content,'Add partner',fields({}),save({}));for(const p of partners){card(content,p.name,[p.contact,JSON.parse(p.areas_json).join(', '),p.status]);if(['operations','operations_finance'].includes(staff.role))form(content,'Edit '+p.name,fields(p),save(p));}}
async function openOrder(id){currentOrder=id;const [d,p]=await Promise.all([api('/orders/'+id),api('/partners')]);partners=p.partners;content.replaceChildren(node('h2','Order workspace'));button(content,'Back to orders',()=>board());button(content,'Refresh',()=>openOrder(id));button(content,'Invoices & settlement',()=>financeWorkspace(id));const o=d.order,j=d.logistics,grid=node('div',undefined,'grid');content.append(grid);
 card(grid,'Material', ['₹'+o.materialAmount,'Payment: '+o.paymentState,'Collector proceeds exclude logistics deductions.']);card(grid,'Physical goods',[j.state,`Requested ${j.requested} ${j.unit}`,`Accepted receipt: ${j.acceptedQuantity??'Awaiting review'}`,`Returned ${j.returnedQuantity} ${j.unit}`]);card(grid,'Logistics charge',[j.cost?'₹'+j.cost.amount+' · '+j.cost.basis:'No charge recorded','Payer: recycler',j.costAcknowledged?'Acknowledged by recycler':'Recycler acknowledgment pending']);
 if(j.schedule)card(content,'Current schedule',[j.schedule.partnerName+' · '+j.schedule.partnerContact,localDate(j.schedule.start)+' – '+localDate(j.schedule.end),j.schedule.instructions]);
 const action=(kind,v)=>mutate('/orders/'+id+'/'+kind,'POST',{expectedVersion:o.version,...v},id);
 if(['operations','operations_finance'].includes(staff.role)&&o.state==='accepted'){
  if(!j.pickup)form(content,'Assign or reschedule collection',[['partnerId','Partner','select',j.schedule?.partnerId||'',partners.filter(x=>x.status==='active').map(x=>[x.id,x.name])],['start','Window start','datetime-local'],['end','Window end','datetime-local'],['instructions','Collection instructions','textarea',j.schedule?.instructions||''],['message','Reason for this schedule','textarea']],v=>action('schedule',{...v,start:new Date(v.start).toISOString(),end:new Date(v.end).toISOString()}));
  form(content,'Record logistics estimate or final charge',[['amount','Total logistics charge ₹','text'],['basis','Charge basis','select','estimate',[['estimate','Estimate'],['final','Final']]],['payee','Logistics payee'],['source','Quote or invoice reference'],['message','Reason for charge change','textarea']],v=>action('cost',v));
  if(j.state==='picked_up')form(content,'Record partner transit update',[['message','Update and source','textarea']],v=>action('in-transit',v));
  if(j.pickup&&j.state!=='returned')form(content,'Arrange a return',[['message','Return reason, partner and instructions','textarea']],v=>action('return-request',v));
  form(content,'Report an issue',[['message','Issue details','textarea']],v=>action('issue',v));
  form(content,'Add restricted operations note',[['message','Staff-only note','textarea']],v=>action('internal-note',v));
 }
 content.append(node('h2','Issues'));if(!d.cases.length)content.append(node('p','No issues recorded.'));for(const issue of d.cases){const c=card(content,issue.state,[issue.reason,issue.resolution||'Awaiting review']);if(issue.state==='open'&&['operations','operations_finance'].includes(staff.role))form(c,'Resolve issue',[['message','Resolution and evidence reference','textarea']],v=>action('resolve-issue',{...v,caseId:issue.id}));}
 content.append(node('h2','Activity & evidence'));for(const e of d.records){const details=node('details');details.append(node('summary',e.kind+' · '+localDate(e.createdAt)),node('p','Recorded by '+e.actorName,'meta'),node('pre',recordText(e.data)));for(const file of e.data.fileIds||[]){const link=node('a','Open evidence photo');link.href='/api/ops/orders/'+id+'/photos/'+file;link.target='_blank';link.rel='noopener';details.append(link);}content.append(details);}
}
document.querySelector('#orders').onclick=()=>guard(()=>board());document.querySelector('#partners').onclick=()=>guard(showPartners);
function signIn(){staff=null;document.querySelector('#facilities').hidden=true;document.querySelector('#identity').textContent='Staff sign-in';content.replaceChildren(node('h2','Your personal invitation'));const f=node('form'),input=field(f,'code','Invitation code','password');input.autocomplete='off';input.maxLength=68;const b=node('button','Sign in');f.append(b);f.onsubmit=e=>{e.preventDefault();guard(async()=>{b.disabled=true;try{await api('/auth/invitation','POST',{code:input.value.trim()});input.value='';await start();}finally{b.disabled=false;}});};content.append(f,node('p','Each invitation is issued to one staff member and works once. Request a new invitation after signing out.'));}
async function start(){try{staff=(await api('/me')).staff;document.querySelector('#facilities').hidden=!['operations','operations_finance'].includes(staff.role);document.querySelector('#identity').textContent=staff.name+' · '+staff.role;pending();await dashboard();}catch(e){if(e.status===401)signIn();else throw e;}}
document.querySelector('#signout').onclick=()=>guard(async()=>{await api('/auth/logout','POST',{});if(staff)sessionStorage.removeItem(key());signIn();pending();});
connectERP({api,node,content,button,guard,openOrder,form,field,mutate,staff:()=>staff});
document.querySelector('#dashboard').onclick=()=>guard(dashboard);
connectFacilityReview({api,content,node,button,field,form,mutate});
document.querySelector('#facilities').onclick=()=>guard(()=>facilityQueue());
guard(start);
